{
  "settings": [
    {
      "name": "default_null_order",
      "input_type": "VARCHAR",
      "scope": "LOCAL",
      "evidence": "Use the `default_null_order` option to change the default `NULL` sorting order to either `NULLS_FIRST`, `NULLS_LAST`, `NULLS_FIRST_ON_ASC_LAST_ON_DESC` or `NULLS_LAST_ON_ASC_FIRST_ON_DESC`:",
      "default_kind": "literal",
      "default_value": "'NULLS_LAST_ON_ASC_FIRST_ON_DESC'",
      "default_evidence": "To match PostgreSQL in both directions, set `default_null_order = 'NULLS_LAST_ON_ASC_FIRST_ON_DESC'`."
    },
    {
      "name": "default_order",
      "input_type": "VARCHAR",
      "scope": "LOCAL",
      "evidence": "Use the `default_order` option to change the direction of the default sorting order to either `DESC` or `ASC`:",
      "default_kind": "literal",
      "default_value": "ASC",
      "default_evidence": "By default, DuckDB sorts `ASC` and `NULLS LAST`, i.e., the values are sorted in ascending order and `NULL` values are placed last."
    }
  ]
}
